package net.levex.favoritefriends;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(FavoriteFriendsConfig.GROUP)
public interface FavoriteFriendsConfig extends Config
{
	String GROUP = "favorite-friends";

	@ConfigItem(
		keyName = "pinnedFriends",
		name = "Pinned friends",
		description = "Internal storage for pinned friend names",
		hidden = true
	)
	default String pinnedFriends()
	{
		return "";
	}

	@ConfigItem(
		keyName = "pinDisplayMode",
		name = "Pin display mode",
		description = "How pinned friends are highlighted in the friends list"
	)
	default PinDisplayMode pinDisplayMode()
	{
		return PinDisplayMode.STAR_ICON;
	}

	@ConfigItem(
		keyName = "pinIcon",
		name = "Pin icon",
		description = "Icon shown beside pinned friends"
	)
	default PinIcon pinIcon()
	{
		return PinIcon.HEART;
	}

	@ConfigItem(
		keyName = "pinColor",
		name = "Pin color",
		description = "Text color for pinned friends when the pin display mode is set to custom color"
	)
	default Color pinColor()
	{
		return Color.YELLOW;
	}
}

package net.levex.favoritefriends;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Friend;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.Nameable;
import net.runelite.api.ScriptID;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.NameableNameChanged;
import net.runelite.api.events.RemovedFriend;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Favorite Friends",
	description = "Pin friends to the top of your friends list and reorder them via the right-click menu"
)
public class FavoriteFriendsPlugin extends Plugin
{
	private static final String PIN_FRIEND = "Pin friend";
	private static final String UNPIN_FRIEND = "Unpin friend";
	private static final String MOVE_UP = "Move up";
	private static final String MOVE_DOWN = "Move down";
	private static final int PIN_ICON_SIZE = 13;
	private static final int DEFAULT_ROW_HEIGHT = 14;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private FavoriteFriendsConfig config;

	@Inject
	private PinnedFriendsStore pinnedFriendsStore;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private ChatIconManager chatIconManager;

	private final Map<String, RowSnapshot> widgetSnapshots = new HashMap<>();

	private int pinIconId = -1;
	private String currentlyLayouting;

	@Provides
	FavoriteFriendsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FavoriteFriendsConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadPinIcon();
		rebuildFriendsList();
	}

	@Override
	protected void shutDown()
	{
		widgetSnapshots.clear();
		rebuildFriendsList();
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		final int groupId = WidgetUtil.componentToInterface(event.getActionParam1());
		if (groupId != InterfaceID.FRIENDS || !"Message".equals(event.getOption()))
		{
			return;
		}

		final String friend = Text.toJagexName(Text.removeTags(event.getTarget()));
		final List<String> pinnedFriends = pinnedFriendsStore.getPinned();
		final int pinnedIndex = indexOfPinned(pinnedFriends, friend);
		final boolean isPinned = pinnedIndex >= 0;

		client.getMenu().createMenuEntry(-1)
			.setOption(isPinned ? UNPIN_FRIEND : PIN_FRIEND)
			.setType(MenuAction.RUNELITE)
			.setTarget(event.getTarget())
			.onClick(e -> handlePinToggle(friend));

		if (isPinned)
		{
			if (pinnedIndex > 0)
			{
				client.getMenu().createMenuEntry(-1)
					.setOption(MOVE_UP)
					.setType(MenuAction.RUNELITE)
					.setTarget(event.getTarget())
					.onClick(e -> handleMove(friend, true));
			}

			if (pinnedIndex < pinnedFriends.size() - 1)
			{
				client.getMenu().createMenuEntry(-1)
					.setOption(MOVE_DOWN)
					.setType(MenuAction.RUNELITE)
					.setTarget(event.getTarget())
					.onClick(e -> handleMove(friend, false));
			}
		}
	}

	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (pinIconId == -1 || config.pinDisplayMode() != PinDisplayMode.STAR_ICON)
		{
			return;
		}

		switch (event.getEventName())
		{
			case "friendsChatSetText":
			{
				final Object[] objectStack = client.getObjectStack();
				final int objectStackSize = client.getObjectStackSize();
				final String rsn = (String) objectStack[objectStackSize - 1];
				final String sanitized = Text.toJagexName(Text.removeTags(rsn));
				currentlyLayouting = pinnedFriendsStore.isPinned(sanitized) ? sanitized : null;

				if (currentlyLayouting != null)
				{
					objectStack[objectStackSize - 1] = rsn + " <img=" + chatIconManager.chatIconIndex(pinIconId) + ">";
				}
				break;
			}
			case "friendsChatSetPosition":
				if (currentlyLayouting == null)
				{
					return;
				}

				final int[] intStack = client.getIntStack();
				final int intStackSize = client.getIntStackSize();
				intStack[intStackSize - 4] += PIN_ICON_SIZE + 1;
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.FRIENDS_UPDATE)
		{
			clientThread.invokeLater(() -> refreshFriendsList(true));
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!FavoriteFriendsConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("pinIcon".equals(event.getKey()))
		{
			loadPinIcon();
		}
		else
		{
			rebuildFriendsList();
		}
	}

	@Subscribe
	public void onNameableNameChanged(NameableNameChanged event)
	{
		final Nameable nameable = event.getNameable();
		if (!(nameable instanceof Friend))
		{
			return;
		}

		final String prevName = nameable.getPrevName();
		if (prevName != null)
		{
			pinnedFriendsStore.rename(
				Text.toJagexName(prevName),
				Text.toJagexName(nameable.getName())
			);
		}
	}

	@Subscribe
	public void onRemovedFriend(RemovedFriend event)
	{
		pinnedFriendsStore.unpin(Text.toJagexName(event.getNameable().getName()));
	}

	private void handlePinToggle(String friend)
	{
		if (pinnedFriendsStore.isPinned(friend))
		{
			pinnedFriendsStore.unpin(friend);
			sendConsoleMessage(friend + " has been unpinned.");
		}
		else
		{
			pinnedFriendsStore.pin(friend);
			sendConsoleMessage(friend + " has been pinned.");
		}
	}

	private void handleMove(String friend, boolean up)
	{
		final boolean moved = up ? pinnedFriendsStore.moveUp(friend) : pinnedFriendsStore.moveDown(friend);
		if (moved)
		{
			sendConsoleMessage(friend + " moved " + (up ? "up" : "down") + " in your pinned friends.");
		}
	}

	private void sendConsoleMessage(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.value(message)
			.build());
	}

	private void rebuildFriendsList()
	{
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}

			final Widget list = client.getWidget(InterfaceID.Friends.LIST);
			if (list == null)
			{
				return;
			}

			client.runScript(
				ScriptID.FRIENDS_UPDATE,
				InterfaceID.Friends.LIST_CONTAINER,
				InterfaceID.Friends.SORT_NAME,
				InterfaceID.Friends.SORT_RECENT,
				InterfaceID.Friends.SORT_WORLD,
				InterfaceID.Friends.SORT_LEGACY,
				InterfaceID.Friends.LIST,
				InterfaceID.Friends.SCROLLBAR,
				InterfaceID.Friends.LOADING,
				InterfaceID.Friends.TOOLTIP
			);
		});
	}

	private void loadPinIcon()
	{
		final PinIcon selectedIcon = config.pinIcon();
		clientThread.invokeLater(() -> spriteManager.getSpriteAsync(selectedIcon.getSpriteId(), 0, sprite ->
		{
			if (sprite == null)
			{
				return;
			}

			if (pinIconId == -1)
			{
				pinIconId = chatIconManager.registerChatIcon(
					ImageUtil.resizeImage(sprite, PIN_ICON_SIZE, PIN_ICON_SIZE));
			}
			else
			{
				chatIconManager.updateChatIcon(
					pinIconId, ImageUtil.resizeImage(sprite, PIN_ICON_SIZE, PIN_ICON_SIZE));
			}

			rebuildFriendsList();
		}));
	}

	void refreshFriendsList(boolean gameRebuilt)
	{
		final Widget list = client.getWidget(InterfaceID.Friends.LIST);
		if (list == null)
		{
			return;
		}

		final List<FriendEntry> entries = collectEntries(list);
		if (entries.isEmpty())
		{
			return;
		}

		final Map<String, FriendEntry> entriesByName = new LinkedHashMap<>();
		for (FriendEntry entry : entries)
		{
			final String key = PinnedFriendsStore.normalize(entry.name);
			captureSnapshot(key, entry, gameRebuilt);
			entriesByName.put(key, entry);
		}

		final List<String> pinned = pinnedFriendsStore.getPinned();
		final List<FriendEntry> ordered = new ArrayList<>();

		for (String pinnedName : pinned)
		{
			final FriendEntry entry = entriesByName.remove(PinnedFriendsStore.normalize(pinnedName));
			if (entry != null)
			{
				ordered.add(entry);
			}
		}

		final int pinnedRowCount = ordered.size();
		final List<FriendEntry> unpinned = new ArrayList<>(entriesByName.values());
		unpinned.sort(Comparator.comparingInt(this::getSnapshotY));
		ordered.addAll(unpinned);

		final int rowHeight = getRowHeight(ordered);
		for (int i = 0; i < ordered.size(); i++)
		{
			final FriendEntry entry = ordered.get(i);
			updatePinColor(entry, i < pinnedRowCount);
			positionEntry(entry, i * rowHeight);
		}
	}

	private List<FriendEntry> collectEntries(Widget list)
	{
		final List<FriendEntry> entries = new ArrayList<>();
		final Widget[] children = list.getDynamicChildren();
		if (children == null)
		{
			return entries;
		}

		FriendEntry current = null;
		for (Widget child : children)
		{
			if (child == null)
			{
				continue;
			}

			if (isNameWidget(child))
			{
				final String name = getFriendName(child);
				current = name != null ? new FriendEntry(child, name) : null;
				if (current != null)
				{
					entries.add(current);
				}
			}
			else if (current != null)
			{
				current.members.add(child);
			}
		}

		return entries;
	}

	private static boolean isNameWidget(Widget child)
	{
		final String name = child.getName();
		final String text = child.getText();
		return name != null && !name.isEmpty() && text != null && !text.isEmpty();
	}

	private void positionEntry(FriendEntry entry, int y)
	{
		for (Widget member : entry.members)
		{
			member.setPos(member.getRelativeX(), y);
			member.revalidate();
		}
	}

	private void captureSnapshot(String key, FriendEntry entry, boolean gameRebuilt)
	{
		if (gameRebuilt || !widgetSnapshots.containsKey(key))
		{
			widgetSnapshots.put(key, new RowSnapshot(
				entry.nameWidget.getRelativeY(),
				entry.nameWidget.getTextColor()
			));
		}
	}

	private int getSnapshotY(FriendEntry entry)
	{
		final RowSnapshot snapshot = widgetSnapshots.get(PinnedFriendsStore.normalize(entry.name));
		return snapshot != null ? snapshot.originalY : entry.nameWidget.getRelativeY();
	}

	private void updatePinColor(FriendEntry entry, boolean pinned)
	{
		final RowSnapshot snapshot = widgetSnapshots.get(PinnedFriendsStore.normalize(entry.name));
		final int baseColor = snapshot != null ? snapshot.originalTextColor : entry.nameWidget.getTextColor();

		if (pinned && config.pinDisplayMode() == PinDisplayMode.CUSTOM_COLOR)
		{
			entry.nameWidget.setTextColor(config.pinColor().getRGB());
		}
		else
		{
			entry.nameWidget.setTextColor(baseColor);
		}
	}

	private String getFriendName(Widget nameWidget)
	{
		final String text = nameWidget.getText();
		if (text == null || text.isEmpty())
		{
			return null;
		}

		final String name = Text.toJagexName(Text.removeTags(text));
		return name.isEmpty() ? null : name;
	}

	private int getRowHeight(List<FriendEntry> entries)
	{
		return entries.stream()
			.mapToInt(e -> e.nameWidget.getHeight())
			.filter(height -> height > 0)
			.findFirst()
			.orElse(DEFAULT_ROW_HEIGHT);
	}

	private int indexOfPinned(List<String> pinned, String friend)
	{
		final String normalized = PinnedFriendsStore.normalize(friend);
		for (int i = 0; i < pinned.size(); i++)
		{
			if (PinnedFriendsStore.normalize(pinned.get(i)).equals(normalized))
			{
				return i;
			}
		}
		return -1;
	}

	private static final class FriendEntry
	{
		private final Widget nameWidget;
		private final String name;
		private final List<Widget> members = new ArrayList<>();

		private FriendEntry(Widget nameWidget, String name)
		{
			this.nameWidget = nameWidget;
			this.name = name;
			members.add(nameWidget);
		}
	}

	private static final class RowSnapshot
	{
		private final int originalY;
		private final int originalTextColor;

		private RowSnapshot(int originalY, int originalTextColor)
		{
			this.originalY = originalY;
			this.originalTextColor = originalTextColor;
		}
	}
}

package net.levex.favoritefriends;

public enum PinDisplayMode
{
	DISABLED("Disabled"),
	STAR_ICON("Icon"),
	CUSTOM_COLOR("Custom color");

	private final String name;

	PinDisplayMode(String name)
	{
		this.name = name;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package net.levex.favoritefriends;

import net.runelite.api.gameval.SpriteID;

public enum PinIcon
{
	HEART("Heart", SpriteID.League6CombatMasterySmall._13),
	STAR("Star", SpriteID.WorldswitcherStars._4);

	private final String name;
	private final int spriteId;

	PinIcon(String name, int spriteId)
	{
		this.name = name;
		this.spriteId = spriteId;
	}

	int getSpriteId()
	{
		return spriteId;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package net.levex.favoritefriends;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class PinnedFriendsStore
{
	private final ConfigManager configManager;

	@Inject
	PinnedFriendsStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public List<String> getPinned()
	{
		final String raw = configManager.getConfiguration(FavoriteFriendsConfig.GROUP, "pinnedFriends");
		if (raw == null || raw.isEmpty())
		{
			return new ArrayList<>();
		}

		return Arrays.stream(raw.split(","))
			.map(String::trim)
			.filter(s -> !s.isEmpty())
			.collect(Collectors.toCollection(ArrayList::new));
	}

	public boolean isPinned(String name)
	{
		final String normalized = normalize(name);
		return getPinned().stream().anyMatch(p -> normalize(p).equals(normalized));
	}

	public void pin(String name)
	{
		final String normalized = normalize(name);
		final List<String> pinned = getPinned();
		if (pinned.stream().anyMatch(p -> normalize(p).equals(normalized)))
		{
			return;
		}

		pinned.add(name.trim());
		save(pinned);
	}

	public void unpin(String name)
	{
		final String normalized = normalize(name);
		final List<String> pinned = getPinned();
		pinned.removeIf(p -> normalize(p).equals(normalized));
		save(pinned);
	}

	public boolean moveUp(String name)
	{
		final String normalized = normalize(name);
		final List<String> pinned = getPinned();
		final int index = indexOf(pinned, normalized);
		if (index <= 0)
		{
			return false;
		}

		Collections.swap(pinned, index, index - 1);
		save(pinned);
		return true;
	}

	public boolean moveDown(String name)
	{
		final String normalized = normalize(name);
		final List<String> pinned = getPinned();
		final int index = indexOf(pinned, normalized);
		if (index < 0 || index >= pinned.size() - 1)
		{
			return false;
		}

		Collections.swap(pinned, index, index + 1);
		save(pinned);
		return true;
	}

	public void rename(String prevName, String newName)
	{
		final List<String> pinned = getPinned();
		final int index = indexOf(pinned, normalize(prevName));
		if (index < 0)
		{
			return;
		}

		pinned.set(index, newName.trim());
		save(pinned);
	}

	static String normalize(String name)
	{
		return name.trim().toLowerCase(Locale.ENGLISH);
	}

	private int indexOf(List<String> pinned, String normalized)
	{
		for (int i = 0; i < pinned.size(); i++)
		{
			if (normalize(pinned.get(i)).equals(normalized))
			{
				return i;
			}
		}
		return -1;
	}

	private void save(List<String> pinned)
	{
		configManager.setConfiguration(
			FavoriteFriendsConfig.GROUP,
			"pinnedFriends",
			String.join(",", pinned)
		);
	}
}

package net.levex.favoritefriends;

