package net.levex.favoritefriends;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

@RunWith(MockitoJUnitRunner.class)
public class PinnedFriendsStoreTest
{
	@Mock
	private net.runelite.client.config.ConfigManager configManager;

	private PinnedFriendsStore store;

	@Before
	public void setUp()
	{
		store = new PinnedFriendsStore(configManager);
	}

	@Test
	public void testGetPinnedEmpty()
	{
		org.mockito.Mockito.when(configManager.getConfiguration(FavoriteFriendsConfig.GROUP, "pinnedFriends"))
			.thenReturn("");

		assertTrue(store.getPinned().isEmpty());
	}

	@Test
	public void testGetPinnedParsesCommaSeparatedList()
	{
		org.mockito.Mockito.when(configManager.getConfiguration(FavoriteFriendsConfig.GROUP, "pinnedFriends"))
			.thenReturn("Alice,Bob, Charlie");

		assertEquals(Arrays.asList("Alice", "Bob", "Charlie"), store.getPinned());
	}

	@Test
	public void testPin()
	{
		org.mockito.Mockito.when(configManager.getConfiguration(FavoriteFriendsConfig.GROUP, "pinnedFriends"))
			.thenReturn("");

		store.pin("Alice");
		org.mockito.Mockito.verify(configManager).setConfiguration(
			FavoriteFriendsConfig.GROUP,
			"pinnedFriends",
			"Alice"
		);
	}

	@Test
	public void testUnpin()
	{
		org.mockito.Mockito.when(configManager.getConfiguration(FavoriteFriendsConfig.GROUP, "pinnedFriends"))
			.thenReturn("Alice");

		store.unpin("Alice");
		org.mockito.Mockito.verify(configManager).setConfiguration(
			FavoriteFriendsConfig.GROUP,
			"pinnedFriends",
			""
		);
	}

	@Test
	public void testIsPinned()
	{
		org.mockito.Mockito.when(configManager.getConfiguration(FavoriteFriendsConfig.GROUP, "pinnedFriends"))
			.thenReturn("Alice");

		assertTrue(store.isPinned("alice"));
	}

	@Test
	public void testMoveUpAndDown()
	{
		org.mockito.Mockito.when(configManager.getConfiguration(FavoriteFriendsConfig.GROUP, "pinnedFriends"))
			.thenReturn("Alice,Bob,Charlie");

		assertTrue(store.moveUp("Bob"));
		org.mockito.Mockito.verify(configManager).setConfiguration(
			FavoriteFriendsConfig.GROUP,
			"pinnedFriends",
			"Bob,Alice,Charlie"
		);

		org.mockito.Mockito.when(configManager.getConfiguration(FavoriteFriendsConfig.GROUP, "pinnedFriends"))
			.thenReturn("Bob,Alice,Charlie");

		assertTrue(store.moveDown("Bob"));
		org.mockito.Mockito.verify(configManager).setConfiguration(
			FavoriteFriendsConfig.GROUP,
			"pinnedFriends",
			"Alice,Bob,Charlie"
		);
	}

	@Test
	public void testMoveUpAtTopReturnsFalse()
	{
		org.mockito.Mockito.when(configManager.getConfiguration(FavoriteFriendsConfig.GROUP, "pinnedFriends"))
			.thenReturn("Alice,Bob");

		assertFalse(store.moveUp("Alice"));
	}

	@Test
	public void testMoveDownAtBottomReturnsFalse()
	{
		org.mockito.Mockito.when(configManager.getConfiguration(FavoriteFriendsConfig.GROUP, "pinnedFriends"))
			.thenReturn("Alice,Bob");

		assertFalse(store.moveDown("Bob"));
	}

	@Test
	public void testRenameKeepsOrder()
	{
		org.mockito.Mockito.when(configManager.getConfiguration(FavoriteFriendsConfig.GROUP, "pinnedFriends"))
			.thenReturn("Alice,Bob,Charlie");

		store.rename("bob", "Robert");

		org.mockito.Mockito.verify(configManager).setConfiguration(
			FavoriteFriendsConfig.GROUP,
			"pinnedFriends",
			"Alice,Robert,Charlie"
		);
	}

	@Test
	public void testRenameUnknownIsNoOp()
	{
		org.mockito.Mockito.when(configManager.getConfiguration(FavoriteFriendsConfig.GROUP, "pinnedFriends"))
			.thenReturn("Alice,Bob");

		store.rename("Zed", "Zod");

		org.mockito.Mockito.verify(configManager, org.mockito.Mockito.never()).setConfiguration(
			org.mockito.Mockito.anyString(),
			org.mockito.Mockito.anyString(),
			org.mockito.Mockito.anyString()
		);
	}
}
